function insertAtHead(head, x) {
  const node = new ListNode(x);
  node.next = head;   // point the new node at the old head
  return node;        // it is the new head
}

ListNode insertAtHead(ListNode head, int x) {
    ListNode node = new ListNode(x);
    node.next = head;   // point the new node at the old head
    return node;        // it is the new head
}

ListNode* insertAtHead(ListNode* head, int x) {
    ListNode* node = new ListNode(x);
    node->next = head;   // point the new node at the old head
    return node;         // it is the new head
}
